test('port-private-descriptor-fields',async()=>{const c=channel(),define=Object.defineProperty;let calls=0,e;try{for(const key of ['get','set'])define(Object.prototype,key,{__proto__:null,configurable:true,get(){calls++;return undefined}});const wait=next(c.port2);c.port1.postMessage({id:1});e=await wait}finally{delete Object.prototype.get;delete Object.prototype.set}log('port-private-descriptor-fields',calls,e?.data.id)});
